package missioncatalog

import (
	"bytes"
	"encoding/json"
	"fmt"
	"os"
	"testing"
)

// This file is test code on purpose. The published file is checked in, and
// this test is its only writer and its only reader in this repo. A consumer
// in a different repo reads the JSON, not a Go symbol.

// publishedFile is the name of the generated file that lists the parameter
// names of each checked-in mission. It is next to this file.
//
// A consumer in a different repo sends these names in CreateMission, and the
// daemon refuses an unknown key and a missing key (ADR-0118). The consumer
// cannot read the CUE of this repo at build time, so this repo publishes the
// names as one JSON file. The consumer keeps a copy and checks its request
// against it (gibson#685, zerocool-plugins#115).
//
// The file is generated. To write it again after a mission changes, run:
//
//	go test ./internal/platform/missioncatalog/ -run TestPublishedParams -update
const publishedFile = "mission-params.json"

// publishedMission is one mission in the published file.
type publishedMission struct {
	// Version is the version that the mission declares in its CUE.
	Version string `json:"version"`
	// Params is the closed set of parameter names, sorted.
	Params []string `json:"params"`
}

// published is the content of the published file.
type published struct {
	// Comment tells a reader of the JSON where the file comes from.
	Comment string `json:"_comment"`
	// Missions maps a catalog mission name to its parameters.
	Missions map[string]publishedMission `json:"missions"`
}

const publishedComment = "Generated from internal/platform/missioncatalog/missions/*.cue in zeroroot-ai/gibson. " +
	"Do not edit. The daemon refuses a parameter that this file does not list, and a request that omits one."

// publishedParams builds the published file from the checked-in missions. The
// bytes are stable: the keys are sorted and the output ends with a newline.
func publishedParams() ([]byte, error) {
	entries, err := Entries()
	if err != nil {
		return nil, err
	}
	if len(entries) == 0 {
		return nil, fmt.Errorf("missioncatalog: no checked-in mission to publish")
	}
	out := published{Comment: publishedComment, Missions: make(map[string]publishedMission, len(entries))}
	for _, e := range entries {
		params := e.DeclaredParams
		if params == nil {
			params = []string{}
		}
		out.Missions[e.Name] = publishedMission{Version: e.Version, Params: params}
	}
	var buf bytes.Buffer
	enc := json.NewEncoder(&buf)
	enc.SetEscapeHTML(false)
	enc.SetIndent("", "  ")
	if err := enc.Encode(out); err != nil {
		return nil, fmt.Errorf("missioncatalog: encode the published parameters: %w", err)
	}
	return buf.Bytes(), nil
}

// publishedDrift compares the committed file with the generated bytes. It
// returns an empty string when they are equal, and a sentence that states the
// fix when they differ.
func publishedDrift(committed, generated []byte) string {
	if bytes.Equal(committed, generated) {
		return ""
	}
	return publishedFile + " differs from the checked-in missions. Run: " +
		"go test ./internal/platform/missioncatalog/ -run TestPublishedParams -update"
}

// The committed file must equal what the missions declare. A rename of a
// parameter in a .cue file fails here until the file is written again, and
// the diff of the file then shows the rename to each consumer (gibson#685).
func TestPublishedParams_FileIsFresh(t *testing.T) {
	generated, err := publishedParams()
	if err != nil {
		t.Fatalf("publishedParams: %v", err)
	}
	// -update is the flag of catalog_test.go. It writes this file too.
	if *updateGolden {
		if err := os.WriteFile(publishedFile, generated, 0o644); err != nil { //nolint:gosec // a checked-in data file, not a secret
			t.Fatalf("write %s: %v", publishedFile, err)
		}
	}
	committed, err := os.ReadFile(publishedFile)
	if err != nil {
		t.Fatalf("read %s: %v", publishedFile, err)
	}
	if msg := publishedDrift(committed, generated); msg != "" {
		t.Fatal(msg)
	}
}

// The failing fixture of the guard: a file with a renamed parameter, a file
// with a missing mission, and an empty file must each be reported as drift.
func TestPublishedParams_DriftIsReported(t *testing.T) {
	t.Parallel()

	generated, err := publishedParams()
	if err != nil {
		t.Fatalf("publishedParams: %v", err)
	}
	if msg := publishedDrift(generated, generated); msg != "" {
		t.Fatalf("equal bytes reported as drift: %s", msg)
	}

	var doc published
	if err := json.Unmarshal(generated, &doc); err != nil {
		t.Fatalf("the generated file is not JSON: %v", err)
	}
	scan, ok := doc.Missions["scan"]
	if !ok || len(scan.Params) == 0 {
		t.Fatalf("the generated file lists no parameter for the scan mission: %+v", doc.Missions)
	}

	renamed := bytes.Replace(generated, []byte(`"`+scan.Params[0]+`"`), []byte(`"renamedParam"`), 1)
	cases := map[string][]byte{
		"a renamed parameter": renamed,
		"an empty file":       {},
		"a missing mission":   []byte(`{"missions":{}}` + "\n"),
	}
	for name, committed := range cases {
		if bytes.Equal(committed, generated) {
			t.Fatalf("%s: the fixture equals the generated file, so it tests nothing", name)
		}
		if msg := publishedDrift(committed, generated); msg == "" {
			t.Errorf("%s: no drift reported", name)
		}
	}
}

// The published names are the names that Render accepts: a request built from
// the file renders, and a request with one more key is refused.
func TestPublishedParams_AgreeWithRender(t *testing.T) {
	t.Parallel()

	generated, err := publishedParams()
	if err != nil {
		t.Fatalf("publishedParams: %v", err)
	}
	var doc published
	if err := json.Unmarshal(generated, &doc); err != nil {
		t.Fatalf("the generated file is not JSON: %v", err)
	}
	if len(doc.Missions) != len(Names()) {
		t.Fatalf("the file lists %d missions, and the catalog holds %d", len(doc.Missions), len(Names()))
	}
	for name, m := range doc.Missions {
		params := make(map[string]string, len(m.Params)+1)
		for _, p := range m.Params {
			params[p] = "v-" + p
		}
		if _, err := Render(t.Context(), name, params); err != nil {
			t.Errorf("%s: a request built from the published names does not render: %v", name, err)
		}
		params["notPublished"] = "x"
		if _, err := Render(t.Context(), name, params); err == nil {
			t.Errorf("%s: Render accepted a parameter that the file does not list", name)
		}
	}
}
